"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { CircleAlert, CircleCheck, Inbox, Search } from "@/components/ui/icons";

// Empty State: generated by UIX from the design system. Same variants and sizes as the Figma component.

const emptyStateVariants = cva(
  "skin-quiet flex flex-col items-center text-center gap-4 px-8 py-10",
  {
    variants: {
      type: {
        default: "[&_[data-slot=art]]:bg-subtle [&_[data-slot=art]]:text-icon-secondary",
        search: "[&_[data-slot=art]]:bg-brand-subtle [&_[data-slot=art]]:text-icon-brand",
        error: "[&_[data-slot=art]]:bg-danger-subtle [&_[data-slot=art]]:text-icon-danger",
        success: "[&_[data-slot=art]]:bg-success-subtle [&_[data-slot=art]]:text-icon-success",
      },
    },
    defaultVariants: {
      type: "default",
    },
  },
);

const emptyStateIcons = { default: Inbox, search: Search, error: CircleAlert, success: CircleCheck };

export interface EmptyStateProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title">,
    VariantProps<typeof emptyStateVariants> {
  title: React.ReactNode;
  description?: React.ReactNode;
  /** Replaces the default icon of this type. */
  icon?: React.ReactNode;
  /** Buttons under the text. */
  actions?: React.ReactNode;
}

const EmptyState = React.forwardRef<HTMLDivElement, EmptyStateProps>(
  ({ className, type, title, description, icon, actions, ...props }, ref) => {
    const Icon = emptyStateIcons[type ?? "default"];
    return (
      <div data-slot="empty-state" data-kind="surface" ref={ref} className={cn(emptyStateVariants({ type }), className)} {...props}>
        <span data-slot="art" className="inline-flex items-center justify-center rounded-full size-[56px]">
          {icon ?? <Icon aria-hidden className="size-[28px]" />}
        </span>
        <h3 className="text-title-large text-fg-primary">{title}</h3>
        {description ? <p className="text-body-medium text-fg-secondary">{description}</p> : null}
        {actions ? <div className="flex items-center gap-2">{actions}</div> : null}
      </div>
    );
  },
);
EmptyState.displayName = "EmptyState";

export { EmptyState, emptyStateVariants };
